// Step 1: Simulated / Real Live Feeds for Tech Hardware & Digital Services
const usdToToman = 110000; // Live USD/USDT Rate in Toman
const cnyToUsd = 0.14;     // Chinese Yuan to USD

const items = [
  {
    category: 'Digital Service',
    name: 'Claude Pro (Monthly)',
    source: 'suzhe.ai',
    currency: 'CNY',
    source_price: 135,
    domestic_market_toman: 2450000,
    settlement_type: 'Crypto (MetaMask USDT)'
  },
  {
    category: 'Digital Service',
    name: 'Cursor Pro (Annual Discount)',
    source: 'suzhe.ai',
    currency: 'USD',
    source_price: 16,
    domestic_market_toman: 2150000,
    settlement_type: 'Crypto (MetaMask USDT)'
  },
  {
    category: 'Hardware (Apple Accessory)',
    name: 'Apple 20W USB-C Power Adapter (Original)',
    source: 'Domestic Black Friday Campaign',
    currency: 'TOMAN',
    source_price: 1350000,
    domestic_market_toman: 1850000,
    settlement_type: 'Rial/Toman Gateway'
  },
  {
    category: 'Gaming Hardware',
    name: 'PS5 DualSense Controller',
    source: 'Wholesale / Flash Sale',
    currency: 'TOMAN',
    source_price: 3650000,
    domestic_market_toman: 4400000,
    settlement_type: 'Rial/Toman Gateway'
  }
];

return items.map(item => {
  let costToman = 0;
  if (item.currency === 'TOMAN') {
    costToman = item.source_price;
  } else if (item.currency === 'USD') {
    costToman = item.source_price * usdToToman;
  } else if (item.currency === 'CNY') {
    costToman = (item.source_price * cnyToUsd) * usdToToman;
  }

  const netProfitToman = item.domestic_market_toman - costToman;
  const marginPercent = ((netProfitToman / costToman) * 100).toFixed(1);

  return {
    json: {
      ...item,
      cost_toman: Math.round(costToman),
      domestic_market_toman: item.domestic_market_toman,
      net_profit_toman: Math.round(netProfitToman),
      margin_percent: parseFloat(marginPercent),
      is_arbitrage_opportunity: marginPercent >= 20.0
    }
  };
});

const deal = $json;
const fa = (n) => Number(n || 0).toLocaleString('fa-IR');

const message = `🚨 *فرصت آربیتراژ بلک‌فرایدی شناسایی شد!*\n\n` +
  `📦 *محصول:* ${deal.name}\n` +
  `🏷 *دسته‌بندی:* ${deal.category}\n` +
  `🌐 *منبع تأمین:* ${deal.source} (${deal.settlement_type})\n\n` +
  `💰 *قیمت خرید (نرمال‌شده):* ${fa(deal.cost_toman)} تومان\n` +
  `📈 *قیمت کف بازار ایران:* ${fa(deal.domestic_market_toman)} تومان\n` +
  `💵 *سود خالص تخمینی:* ${fa(deal.net_profit_toman)} تومان\n` +
  `🚀 *حاشیه سود:* ${deal.margin_percent}%\n\n` +
  `⚡ *وضعیت:* آماده برای خرید با MetaMask یا ثبت سفارش در استور.`;

return [{ json: { formatted_alert: message, ...deal } }];
